11	interface SubmitPickerDeps {
12	    gameDayService: Pick<typeof gameDayService, 'getCurrent'>;
13	    outcomeService: Pick<typeof outcomeService, 'getAdminByGameDay' | 'getPlayerGamesPlayedBeforeGameDay' | 'getRecentAverage' | 'upsert'>;
14	    sendEmailToAllActivePlayers: SendEmailToAllActivePlayersProxy;
15	    getPublicBaseUrl: () => string;
16	}
