25	interface PickerCandidate {
26	    playerId: number;
27	    name: string;
28	    goalie: boolean;
29	    average: number;
30	    age: number | null;
31	}
32	
33	interface TeamDiffs {
34	    diffGoalies: number;
35	    diffAverage: number;
36	    diffUnknownAge: number;
37	    diffAge: number;
38	}
39	
40	interface TeamSplit {
41	    teamA: PickerCandidate[];
42	    teamB: PickerCandidate[];
43	    diffs: TeamDiffs;
44	}
45	
46	/**
47	 * Compares two numbers using an epsilon tolerance to account for floating-point
48	 * imprecision.
49	 *
50	 * @param a - The first number to compare.
51	 * @param b - The second number to compare.
52	 * @param epsilon - The maximum allowed difference to consider the numbers
53	 * equal.
54	 * @returns `0` if the numbers are within `epsilon`, `-1` if `a` is less than
55	 * `b`, or `1` if `a` is greater than `b`.
56	 */
57	const compareNumber = (a: number, b: number, epsilon = 1e-9) => {
58	    const delta = a - b;
59	    if (Math.abs(delta) <= epsilon) return 0;
60	    return delta < 0 ? -1 : 1;
61	};
62	
63	/**
64	 * Compares two nullable numbers, treating null values as coming first in sort
65	 * order.
66	 * @param a - The first number to compare, or null
67	 * @param b - The second number to compare, or null
68	 * @returns A negative number if a comes before b, 0 if equal, or a positive
69	 *          number if a comes after b. Null values are always sorted before
70	 *          non-null values.
71	 */
72	const compareNullableNumberNullsFirst = (a: number | null, b: number | null) => {
73	    if (a === null && b === null) return 0;
74	    if (a === null) return -1;
75	    if (b === null) return 1;
76	    return compareNumber(a, b);
77	};
78	
79	/**
80	 * Computes the total of all numeric values in the provided array.
81	 *
82	 * @param values - The list of numbers to add together.
83	 * @returns The sum of all numbers in the array.
84	 */
85	const sum = (values: number[]) => values.reduce((acc, value) => acc + value, 0);
86	
87	/**
88	 * Iterates over all combinations of k items from a given array and invokes a
89	 * callback for each combination.
90	 *
91	 * @template T - The type of items in the array.
92	 * @param k - The size of each combination (number of items to include).
93	 * @param items - The array of items to generate combinations from.
94	 * @param callback - Function invoked for each combination, receiving:
95	 *   - `included` - Array of items included in the current combination.
96	 *   - `excluded` - Array of items excluded from the current combination.
97	 *   - `includedIndexes` - Indexes of included items in the original array.
98	 *   - `includedMask` - Bitmask representation of included item positions.
99	 * @param mirror - If true, only evaluates combinations where the first item
100	 *   (items[0]) is included, yielding exactly one representative per mirrored
101	 *   pair. Defaults to true.
102	 *
103	 * @example
104	 * ```typescript
105	 * combForeach(2, ['a', 'b', 'c'], (included, excluded, indexes, mask) => {
106	 *   console.log(included); // ['a', 'b'], ['a', 'c'], ['b', 'c']
107	 * });
108	 * ```
109	 */
110	const combForeach = <T>(
111	    k: number,
112	    items: T[],
113	    callback: (included: T[], excluded: T[], includedIndexes: number[], includedMask: bigint) => void,
114	    mirror = true,
115	) => {
116	    const n = items.length;
117	    /* v8 ignore next -- defensive guard for direct helper use */
118	    if (k < 0 || k > n) return;
119	
120	    const included: T[] = [];
121	    const includedIndexes: number[] = [];
122	
123	    const emitSplit = () => {
124	        const excluded: T[] = [];
125	        let includedCursor = 0;
126	
127	        for (let index = 0; index < n; index++) {
128	            if (includedIndexes[includedCursor] === index) {
129	                includedCursor++;
130	            } else {
131	                excluded.push(items[index]);
132	            }
133	        }
134	
135	        let includedMask = 0n;
136	        for (const index of includedIndexes) {
137	            includedMask |= 1n << BigInt(index);
138	        }
139	
140	        callback([...included], excluded, [...includedIndexes], includedMask);
141	    };
142	
143	    const walk = (start: number, needed: number) => {
144	        if (needed === 0) {
145	            emitSplit();
146	            return;
147	        }
148	
149	        for (let index = start; index <= n - needed; index++) {
150	            included.push(items[index]);
151	            includedIndexes.push(index);
152	            walk(index + 1, needed - 1);
153	            included.pop();
154	            includedIndexes.pop();
155	        }
156	    };
157	
158	    // For mirrored team splits, only evaluate combinations where item[0] is
159	    // included. This yields exactly one representative per mirrored pair.
160	    /* v8 ignore next -- current caller always uses mirrored evaluation */
161	    if (mirror) {
162	        /* v8 ignore next -- cannot occur with validated team sizes */
163	        if (k === 0 || n === 0) return;
164	        included.push(items[0]);
165	        includedIndexes.push(0);
166	        walk(1, k - 1);
167	        return;
168	    }
169	
170	    /* v8 ignore next -- current caller always uses mirrored evaluation */
171	    walk(0, k);
172	};
173	
174	/**
175	 * Calculates the differences between two teams across multiple metrics.
176	 * @param teamA - The first team of picker candidates
177	 * @param teamB - The second team of picker candidates
178	 * @param unknownAgeValue - The numeric value to use for players with unknown
179	 * age
180	 * @returns An object containing the differences in goalies, average skill,
181	 * unknown age count, and total age between the two teams
182	 */
183	const calculateDiffs = (
184	    teamA: PickerCandidate[],
185	    teamB: PickerCandidate[],
186	    unknownAgeValue: number,
187	): TeamDiffs => {
188	    const teamAGoalies = sum(teamA.map((player) => player.goalie ? 1 : 0));
189	    const teamBGoalies = sum(teamB.map((player) => player.goalie ? 1 : 0));
190	    const teamAAverage = sum(teamA.map((player) => player.average));
191	    const teamBAverage = sum(teamB.map((player) => player.average));
192	    const teamAUnknownAge = sum(teamA.map((player) => player.age === null ? 1 : 0));
193	    const teamBUnknownAge = sum(teamB.map((player) => player.age === null ? 1 : 0));
194	    const teamAAge = sum(teamA.map((player) => player.age ?? unknownAgeValue));
195	    const teamBAge = sum(teamB.map((player) => player.age ?? unknownAgeValue));
196	
197	    return {
198	        diffGoalies: teamAGoalies - teamBGoalies,
199	        diffAverage: teamAAverage - teamBAverage,
200	        diffUnknownAge: teamAUnknownAge - teamBUnknownAge,
201	        diffAge: teamAAge - teamBAge,
202	    };
203	};
204	
205	const compareDiffs = (left: TeamDiffs, right: TeamDiffs) => {
206	    // Mirrors legacy picker_best_teams ordering:
207	    // ABS(diff_goalies), ABS(diff_played), ABS(diff_average),
208	    // ABS(diff_unknown_age), ABS(diff_age)
209	    const comparisons = [
210	        compareNumber(Math.abs(left.diffGoalies), Math.abs(right.diffGoalies)),
211	        compareNumber(Math.abs(left.diffAverage), Math.abs(right.diffAverage)),
212	        compareNumber(Math.abs(left.diffUnknownAge), Math.abs(right.diffUnknownAge)),
213	        compareNumber(Math.abs(left.diffAge), Math.abs(right.diffAge)),
214	    ];
215	
216	    for (const result of comparisons) {
217	        if (result !== 0) return result;
218	    }
219	
220	    return 0;
221	};
222	
223	/**
224	 * Finds the optimal split of players into two balanced teams.
225	 *
226	 * The function evaluates all possible team combinations and selects the one that minimizes
227	 * the differences in team attributes (e.g., skill level, age). When multiple splits have
228	 * equal differences, the lexicographically smallest team mask is preferred for consistency.
229	 *
230	 * @param players - An array of player candidates to be split into teams. Must contain an even
231	 *                  number of at least 2 players.
232	 * @returns A {@link TeamSplit} object containing the two balanced teams (teamA and teamB) and
233	 *          their calculated differences.
234	 * @throws {ValidationError} If the number of players is less than 2 or not an even number.
235	 * @throws {InternalError} If unable to determine balanced teams (should not occur with valid input).
236	 *
237	 * @remarks
238	 * - The function calculates an average age from players with known ages to handle cases where
239	 *   some players may have null age values.
240	 * - Team balance is determined by comparing differences in various attributes using
241	 *   {@link calculateDiffs} and {@link compareDiffs}.
242	 * - The algorithm uses bitmasking via {@link combForeach} to efficiently iterate through
243	 *   all possible team combinations.
244	 */
245	const findBestSplit = (players: PickerCandidate[]): TeamSplit => {
246	    /* v8 ignore next -- upstream selection always passes even-sized arrays >= 2 */
247	    if (players.length < 2 || players.length % 2 !== 0) {
248	        throw new ValidationError('Cannot split teams: expected an even number of at least two players.');
249	    }
250	
251	    const teamSize = players.length / 2;
252	    const knownAges = players
253	        .map((player) => player.age)
254	        .filter((age): age is number => age !== null);
255	    const averageKnownAge = knownAges.length > 0 ?
256	        sum(knownAges) / knownAges.length :
257	        0;
258	
259	    let bestSplit: TeamSplit | null = null;
260	    let bestSplitMask: bigint | null = null;
261	    combForeach(teamSize, players, (teamA, teamB, _teamAIndexes, teamAMask) => {
262	        const diffs = calculateDiffs(teamA, teamB, averageKnownAge);
263	
264	        if (!bestSplit) {
265	            bestSplit = { teamA, teamB, diffs };
266	            bestSplitMask = teamAMask;
267	            return;
268	        }
269	
270	        const diffComparison = compareDiffs(diffs, bestSplit.diffs);
271	        if (diffComparison < 0 || (diffComparison === 0 && bestSplitMask !== null && teamAMask < bestSplitMask)) {
272	            bestSplit = { teamA, teamB, diffs };
273	            bestSplitMask = teamAMask;
274	        }
275	    });
276	
277	    /* v8 ignore next -- combForeach always emits at least one split for valid input */
278	    if (!bestSplit) {
279	        throw new InternalError('Unable to determine balanced teams.');
280	    }
281	
282	    return bestSplit;
283	};
284	
285	/**
286	 * Selects a middle outfield player from a list of candidates and returns the
287	 * remaining players.
288	 *
289	 * For even-sized lists, returns all players for splitting with no middle
290	 * player. For odd-sized lists, sorts players by goalie status, average, age,
291	 * and player ID, then selects the middle non-goalie player as the separator.
292	 *
293	 * @param players - Array of picker candidates to process
294	 * @returns An object containing:
295	 *   - playersForSplit: Array of players excluding the middle player
296	 *   - middlePlayer: The selected middle player, or null for even-sized lists
297	 * @throws {InternalError} If unable to select a middle player for odd-sized
298	 * lists.
299	 */
300	const selectMiddleOutfieldPlayer = (players: PickerCandidate[]) => {
301	    if (players.length % 2 === 0) {
302	        return { playersForSplit: players, middlePlayer: null as PickerCandidate | null };
303	    }
304	
305	    let middle = Math.floor(players.filter((player) => !player.goalie).length / 2);
306	    const orderedPlayers = [...players].sort((left, right) =>
307	        compareNumber(left.goalie ? 1 : 0, right.goalie ? 1 : 0) ||
308	        compareNumber(left.average, right.average) ||
309	        compareNullableNumberNullsFirst(left.age, right.age) ||
310	        (left.playerId - right.playerId),
311	    );
312	    let middlePlayer: PickerCandidate | null = null;
313	    const playersForSplit: PickerCandidate[] = [];
314	
315	    for (const player of orderedPlayers) {
316	        const removeCurrentPlayer = middlePlayer === null && middle === 0;
317	        middle--;
318	        if (removeCurrentPlayer) {
319	            middlePlayer = player;
320	        } else {
321	            playersForSplit.push(player);
322	        }
323	    }
324	
325	    /* v8 ignore next -- odd-sized iteration always selects exactly one middle player */
326	    if (!middlePlayer) {
327	        throw new InternalError('Unable to select middle player for odd-sized picker list.');
328	    }
329	
330	    return { playersForSplit, middlePlayer };
331	};
