333	/**
334	 * Builds an HTML email message for team selection notification.
335	 *
336	 * Generates a formatted email containing the two teams that have been picked
337	 * for a game, including clickable links to each player's profile page.
338	 *
339	 * @param options - The configuration object
340	 * @param options.gameDayId - The unique identifier for the game day
341	 * @param options.teamA - Array of players assigned to Team A
342	 * @param options.teamB - Array of players assigned to Team B
343	 * @param options.baseUrl - The base URL for constructing player and game page
344	 * links
345	 * @returns An HTML string formatted as an email body containing team
346	 *          information, player links, and a reference to the game page
347	 */
348	const buildTeamEmail = ({
349	    gameDayId,
350	    teamA,
351	    teamB,
352	    baseUrl,
353	}: {
354	    gameDayId: number;
355	    teamA: PickerCandidate[];
356	    teamB: PickerCandidate[];
357	    baseUrl: string;
358	}) => {
359	    const gameUrl = `${baseUrl}/footy/game/${gameDayId}`;
360	    const formatPlayerLinks = (players: PickerCandidate[]) => players
361	        .slice()
362	        .sort((left, right) => left.name.localeCompare(right.name))
363	        .map((player) => `<a href="${baseUrl}/footy/player/${player.playerId}">${player.name}</a>`)
364	        .join('<br />\n');
365	
366	    return [
367	        '<div>',
368	        `<p>The teams for game ${gameDayId} have been picked. They are:</p>`,
369	        '<p><strong>Team A</strong><br />',
370	        `${formatPlayerLinks(teamA)}`,
371	        '</p>',
372	        '<p><strong>vs</strong></p>',
373	        '<p><strong>Team B</strong><br />',
374	        `${formatPlayerLinks(teamB)}`,
375	        '</p>',
376	        '<p>Remember you can still change your response if you need to, whether you are in the game or not. ',
377	        'If players withdraw or new ones come along, the teams may be re-picked.</p>',
378	        `<p>Visit the game page at <a href="${gameUrl}">${gameUrl}</a>.</p>`,
379	        '<p>Cheers,<br />Jon</p>',
380	        '</div>',
381	    ].join('\n');
382	};
383	
384	/**
385	 * Core logic for submitting team picker selections and assigning players to teams.
386	 *
387	 * This function performs the following operations:
388	 * 1. Validates that at least two players are selected
389	 * 2. Retrieves the current game day and player outcomes
390	 * 3. Clears existing team assignments for all eligible players
391	 * 4. Validates selected players have 'Yes' responses
392	 * 5. Calculates player statistics (average performance, age, position)
393	 * 6. Determines optimal team split based on player averages
394	 * 7. Assigns players to teams and persists assignments
395	 * 8. Sends email notification to all active players with team assignments
396	 *
397	 * @param data - Array of picker inputs containing player selections and metadata
398	 * @param deps - Service dependencies for game day, outcomes, email, and configuration (defaults provided)
399	 * @returns Promise that resolves when team assignments are complete and notifications sent
400	 * @throws {ValidationError} If fewer than two players are selected.
401	 * @throws {NotFoundError} If no current game day is available.
402	 * @throws {ValidationError} If a selected player is not available for the game day.
403	 * @throws {ValidationError} If a selected player has not confirmed participation with 'Yes'.
404	 */
405	export async function SubmitPickerCore(
406	    data: SubmitPickerInput,
407	    deps: SubmitPickerDeps = defaultDeps,
408	): Promise<void> {
409	    const selectedPlayerIds = Array.from(new Set(data.map((item) => item.playerId)));
410	    if (selectedPlayerIds.length < 2) {
411	        throw new ValidationError('At least two players are required to pick teams.');
412	    }
413	
414	    const gameDay = await deps.gameDayService.getCurrent();
415	    if (!gameDay) {
416	        throw new NotFoundError('No current game day available for picking teams.');
417	    }
418	
419	    const history = gameDay.pickerGamesHistory ?? 10;
420	    const outcomes = await deps.outcomeService.getAdminByGameDay(gameDay.id);
421	
422	    // Legacy `game_reset_teams`: clear teams for the whole game before re-picking.
423	    await Promise.all(outcomes
424	        .filter((outcome) => outcome.id > 0)
425	        .map((outcome) =>
426	            deps.outcomeService.upsert({
427	                gameDayId: gameDay.id,
428	                playerId: outcome.playerId,
429	                team: null,
430	            })));
431	
432	    const selectedOutcomes = selectedPlayerIds.map((playerId) => {
433	        const row = outcomes.find((outcome) => outcome.playerId === playerId);
434	        if (!row) {
435	            throw new ValidationError(`Selected player ${playerId} is not available for this game day.`);
436	        }
437	        if (row.response !== 'Yes') {
438	            throw new ValidationError(`Selected player ${playerId} does not have a 'Yes' response.`);
439	        }
440	        return row;
441	    });
442	
443	    const candidates = await Promise.all(selectedOutcomes.map(async (row) => {
444	        const average = await deps.outcomeService.getRecentAverage(gameDay.id, row.playerId, history);
445	        const born = row.player.born ?? null;
446	        const age = (born !== null && born < 1995) ? gameDay.year - born : null;
447	        return {
448	            playerId: row.playerId,
449	            name: row.player.name ?? `Player ${row.playerId}`,
450	            goalie: row.goalie === true,
451	            average,
452	            age,
453	        } satisfies PickerCandidate;
454	    }));
455	
